const messages: Record<Locale, Messages> = { en, "zh-CN": zhCN, "zh-TW": zhTW, ja, es, fr };

export function isLocale(value: string | null | undefined): value is Locale {
  return SUPPORTED_LOCALES.some((locale) => locale.code === value);
}

export function intlLocale(locale: Locale) {
  return SUPPORTED_LOCALES.find((item) => item.code === locale)?.intl || "en-US";
}

export function translate(locale: Locale, key: string, variables?: TranslationVariables) {
  const localized = messages[locale][key as MessageKey];
  const fallback = en[key as MessageKey];
  const productInfo = isProductInfoKey(key) ? translateProductInfo(locale, key) : "";
  const template = localized || fallback || translateFeature(locale, key) || translateRisk(locale, key) || translateUx(locale, key) || productInfo || key;
  if (!variables) return template;
  return template.replace(/\{(\w+)\}/g, (match, name: string) => String(variables[name] ?? match));
}
